def base_do_portal(apps, schema_editor):
    """O portal da Saitro conta KB/MB em base 1024 (703,70 KB = 720.593 bytes, conferido em 13/11/2026).
    A migration 0199 gravou o mapeamento do GSIM com base 1000: corrige SÓ quem ainda está nesse padrão."""
    Integracao = apps.get_model("ProjetoEstoque", "M2MIntegracao")
    for cfg in Integracao.objects.all():
        mapa = cfg.mapeamento or {}
        consumo = mapa.get("consumo")
        if isinstance(consumo, dict) and consumo.get("unidade_no_valor") and consumo.get("base") == 1000:
            consumo["base"] = 1024
            cfg.mapeamento = mapa
            cfg.save(update_fields=["mapeamento"])


